const items = $input.all();

const stats = {
  total: items.length,
  byLocation: { HIC: 0, ICV: 0 },
  byStatus: { REQUESTED: 0, APPROVED: 0, REJECTED: 0, CANCELLED: 0, COMPLETED: 0, NO_SHOW: 0 },
  bySpecialty: {}
};

for (const item of items) {
  const a = item.json;
  if (a.locationName && a.locationName.includes('Internacional')) stats.byLocation.HIC++;
  else stats.byLocation.ICV++;

  if (stats.byStatus[a.statusCode] !== undefined) stats.byStatus[a.statusCode]++;

  const spec = a.specialtyName || 'Otras';
  stats.bySpecialty[spec] = (stats.bySpecialty[spec] || 0) + 1;
}

const html = `
  <div style="font-family: Arial, sans-serif; color: #1e293b; max-width: 650px; padding: 20px; border: 1px solid #e2e8f0; border-radius: 8px;">
    <h2 style="color: #0284c7; margin-top: 0;">Reporte Operativo Diario — FCV Citas</h2>
    <p><strong>Fecha del Reporte:</strong> ${new Date().toLocaleDateString()}</p>
    <p><strong>Total de Citas Registradas:</strong> ${stats.total}</p>
    <hr style="border: none; border-top: 1px solid #cbd5e1; margin: 15px 0;" />
    <h3>Distribución por Sede</h3>
    <ul>
      <li>Hospital Internacional de Colombia (HIC): ${stats.byLocation.HIC}</li>
      <li>Instituto Cardiovascular (ICV): ${stats.byLocation.ICV}</li>
    </ul>
    <h3>Distribución por Estado</h3>
    <ul>
      <li>Aprobadas: ${stats.byStatus.APPROVED}</li>
      <li>Completadas (Atendidas): ${stats.byStatus.COMPLETED}</li>
      <li>Inasistencias (No Show): ${stats.byStatus.NO_SHOW}</li>
      <li>Canceladas: ${stats.byStatus.CANCELLED}</li>
      <li>Rechazadas: ${stats.byStatus.REJECTED}</li>
      <li>Pendientes (Requested): ${stats.byStatus.REQUESTED}</li>
    </ul>
    <p style="color: #64748b; font-size: 12px; margin-top: 20px;">Generado automáticamente por el flujo de automatización FCV n8n.</p>
  </div>
`;

return [{
  json: {
    reportDate: new Date().toISOString(),
    totalAppointments: stats.total,
    summaryHtml: html
  }
}];
